package net.civeira.phylax.feature.access.oauthclient.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.access.oauthclient.domain.OauthClient;
import net.civeira.phylax.feature.access.oauthclient.domain.valueobject.ClientNameVO;

class ClientNameValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of client name of oauth client")
  void test_client_name_value_holder_assign_plain_value() {
    Object holder = new Object();
    ClientNameValueHolder<Object> value = new ClientNameValueHolder<>(holder);
    Assertions.assertSame(holder, value.clientName("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getClientNameValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getClientName().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.clientNameNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getClientNameValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getClientName().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of client name of oauth client")
  void test_client_name_value_holder_assign_value_object() {
    Object holder = new Object();
    ClientNameValueHolder<Object> value = new ClientNameValueHolder<>(holder);
    ClientNameVO vo = ClientNameVO.from("one");
    Assertions.assertFalse(value.getClientNameValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.clientName(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getClientNameValue().orElseThrow());
    Assertions.assertSame(holder, value.clientName(Optional.empty()));
    Assertions.assertFalse(value.getClientNameValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.clientName(Optional.of(vo)));
    Assertions.assertSame(vo, value.getClientNameValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of client name of oauth client against the original")
  void test_client_name_value_holder_read() {
    Object holder = new Object();
    ClientNameValueHolder<Object> value = new ClientNameValueHolder<>(holder);
    ClientNameVO vo = ClientNameVO.from("one");
    ClientNameVO other = ClientNameVO.from("one");
    OauthClient original = Mockito.mock(OauthClient.class);
    Mockito.when(original.getClientNameValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readClientName(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readClientName(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.clientName(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readClientName(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readClientName(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of client name of oauth client")
  void test_client_name_value_holder_unset() {
    Object holder = new Object();
    ClientNameValueHolder<Object> value = new ClientNameValueHolder<>(holder);
    ClientNameVO vo = ClientNameVO.from("one");
    value.clientName(vo);
    Assertions.assertSame(holder, value.unsetClientNameIfMatches("clientName_other"));
    Assertions.assertTrue(value.getClientNameValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetClientNameIfMatches("clientName"));
    Assertions.assertFalse(value.getClientNameValue().isPresent(),
        "The field name must clear the value");
    value.clientName(vo);
    Assertions.assertSame(holder, value.unsetClientName());
    Assertions.assertFalse(value.getClientNameValue().isPresent(), "Unset must clear the value");
  }
}
